@if($can('branding.update'))<div id="theme-preview" style="padding:12px;border-radius:6px;background:{{ $organization->primary_color }}"><span id="theme-primary-label">Primary preview</span> <span id="theme-accent-preview" style="padding:4px 8px;border-radius:4px;background:{{ $organization->accent_color }}">Accent preview</span></div><p><small>Text color is chosen automatically for readable contrast.</small></p><form method="post" action="{{ route('branding.reset',$organization) }}">@csrf<button>Restore default colors</button></form><script>document.addEventListener('DOMContentLoaded',()=>{const p=document.querySelector('[name=primary_color]'),a=document.querySelector('[name=accent_color]'),box=document.getElementById('theme-preview'),label=document.getElementById('theme-primary-label'),accent=document.getElementById('theme-accent-preview');if(!p||!a||!box)return;const text=c=>{let rgb=[1,3,5].map(i=>parseInt(c.slice(i,i+2),16)/255).map(x=>x<=0.04045?x/12.92:Math.pow((x+0.055)/1.055,2.4));return 0.2126*rgb[0]+0.7152*rgb[1]+0.0722*rgb[2]>0.179?'#000':'#fff'};const refresh=()=>{box.style.background=p.value;label.style.color=text(p.value);accent.style.background=a.value;accent.style.color=text(a.value)};p.addEventListener('input',refresh);a.addEventListener('input',refresh);refresh()});</script>@endif</section>@endif
